INSERT INTO public.menu_items (slug, category_id, name, price, description, image_url, is_popular, badge, caffeine, calories, is_available, is_customizable, display_order) SELECT 'vietnamese-banh-mi-garlic-chicken', id, 'Garlic Chicken Banh Mi', 8.00, 'A fresh, crusty baguette loaded with juicy, garlic-marinated chicken, crisp pickled carrots and daikon, fresh cilantro, and rich homemade mayonnaise. Bursting with savory garlic flavor and balanced with tangy, refreshing pickles for the perfect bite.', 'https://152864630.cdn6.editmysite.com/uploads/1/5/2/8/152864630/5OUFV6D6I6KKFLQ73OW2SIV7.jpeg?width=1280&dpr=1', false, 'Vietnamese', 'None', '550 kcal', true, false, 75 FROM public.categories WHERE slug = 'banh-mi' ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, price = EXCLUDED.price, description = EXCLUDED.description, image_url = EXCLUDED.image_url, is_popular = EXCLUDED.is_popular, badge = EXCLUDED.badge, caffeine = EXCLUDED.caffeine, calories = EXCLUDED.calories, is_available = EXCLUDED.is_available, is_customizable = EXCLUDED.is_customizable, display_order = EXCLUDED.display_order;
INSERT INTO public.menu_items (slug, category_id, name, price, description, image_url, is_popular, badge, caffeine, calories, is_available, is_customizable, display_order) SELECT 'vietnamese-banh-mi-beef', id, 'Beef Banh Mi', 9.50, 'Tender slices of premium beef, marinated and griddled to perfection, served in a warm, crusty French baguette. Finished with our homemade sate sauce, pickled carrots and daikon, fresh cilantro, and a touch of creamy house-made mayonnaise. A rich and flavorful take on the classic banh mi.', 'https://152864630.cdn6.editmysite.com/uploads/1/5/2/8/152864630/5OUFV6D6I6KKFLQ73OW2SIV7.jpeg?width=1280&dpr=1', false, 'Vietnamese', 'None', '620 kcal', true, false, 76 FROM public.categories WHERE slug = 'banh-mi' ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, price = EXCLUDED.price, description = EXCLUDED.description, image_url = EXCLUDED.image_url, is_popular = EXCLUDED.is_popular, badge = EXCLUDED.badge, caffeine = EXCLUDED.caffeine, calories = EXCLUDED.calories, is_available = EXCLUDED.is_available, is_customizable = EXCLUDED.is_customizable, display_order = EXCLUDED.display_order;
